class os_developer_options {
    char data[408];
    int debug_menus;

public:
    enum flags_t { FLAG_DEBUG_MENUS };
    static os_developer_options *inst();
    bool is_flagged(flags_t) const { return debug_menus; }
};

extern os_developer_options *developer_options_instance;
__asm__(".equ developer_options_instance, 0x0045B180");

os_developer_options *os_developer_options::inst()
{
    return developer_options_instance;
}

class FEEntityManager {
    char data[656];
    int in_flyin;

public:
    enum {
        CAM_POS_WALL_1,
        CAM_POS_WALL_2_IN,
        CAM_POS_WALL_2_OUT,
        CAM_POS_WALL_3_MAP
    };
    bool InFlyin() const { return in_flyin; }
    void JumpTo(int);
};

class FEManager {
    char data[12];

public:
    FEEntityManager *em;
};

struct FEDebugMenuVTable {
    char data[152];
    short up_adjustment;
    short up_padding;
    void (*up)(void *, int);
    short down_adjustment;
    short down_padding;
    void (*down)(void *, int);
    short left_adjustment;
    short left_padding;
    void (*left)(void *, int);
    short right_adjustment;
    short right_padding;
    void (*right)(void *, int);
    short cross_adjustment;
    short cross_padding;
    void (*cross)(void *, int);
    short triangle_adjustment;
    short triangle_padding;
    void (*triangle)(void *, int);
    short square_adjustment;
    short square_padding;
    void (*square)(void *, int);
    short circle_adjustment;
    short circle_padding;
    void (*circle)(void *, int);
};

class FEDebugMenu {
    char data[116];
    FEDebugMenuVTable *vtable;

public:
    void OnUp(int controller)
    {
        vtable->up((char *)this + vtable->up_adjustment, controller);
    }
    void OnDown(int controller)
    {
        vtable->down((char *)this + vtable->down_adjustment, controller);
    }
    void OnLeft(int controller)
    {
        vtable->left((char *)this + vtable->left_adjustment, controller);
    }
    void OnRight(int controller)
    {
        vtable->right((char *)this + vtable->right_adjustment, controller);
    }
    void OnCross(int controller)
    {
        vtable->cross((char *)this + vtable->cross_adjustment, controller);
    }
    void OnTriangle(int controller)
    {
        vtable->triangle((char *)this + vtable->triangle_adjustment, controller);
    }
    void OnSquare(int controller)
    {
        vtable->square((char *)this + vtable->square_adjustment, controller);
    }
    void OnCircle(int controller)
    {
        vtable->circle((char *)this + vtable->circle_adjustment, controller);
    }
};

class FEMenuSystem {
    char data[120];

public:
    void OnButtonPress(int, int);
};

class GraphicalMenuSystem : public FEMenuSystem {
    FEManager *manager;
    int active;
    char data1[224 - 128];
    int usercam;
    char data2[280 - 228];
    int fedbm_up;
    FEDebugMenu *fedbm;

public:
    enum {
        MainMenu,
        ExtrasMenu,
        CreditsMenu,
        HighScoreMenu,
        SurferMenu,
        BeachMenu,
        SaveLoadMenu,
        TrickBookMenu,
        BoardMenu,
        AccompMenu,
        LogbookMenu,
        BuiltVersionMenu,
        TitleMenu,
        Legal,
        OptionsMenu
    };

    void OnButtonPress(int button, int controller);
};

enum {
    FEMENUCMD_SELECT,
    FEMENUCMD_START,
    FEMENUCMD_UP,
    FEMENUCMD_DOWN,
    FEMENUCMD_LEFT,
    FEMENUCMD_RIGHT,
    FEMENUCMD_CROSS,
    FEMENUCMD_TRIANGLE,
    FEMENUCMD_SQUARE,
    FEMENUCMD_CIRCLE
};

__asm__(".equ JumpTo__15FEEntityManageri, 0x001C4C88");
__asm__(".equ OnButtonPress__12FEMenuSystemii, 0x00158CB0");

void GraphicalMenuSystem::OnButtonPress(int button, int controller)
{
	if(os_developer_options::inst()->is_flagged(os_developer_options::FLAG_DEBUG_MENUS) && button == FEMENUCMD_SQUARE)
		fedbm_up = !fedbm_up;
	else if(!fedbm_up)
	{
		if(manager->em->InFlyin())
		{
			int jump_to = -1;
			if(active == MainMenu) jump_to = FEEntityManager::CAM_POS_WALL_1;
			if(active == BeachMenu) jump_to = FEEntityManager::CAM_POS_WALL_3_MAP;
			if(active == AccompMenu) jump_to = FEEntityManager::CAM_POS_WALL_1;
			if(jump_to != -1) manager->em->JumpTo(jump_to);
		}
		if(!usercam) FEMenuSystem::OnButtonPress(button, controller);
	}
	else
	{
		switch(button)
		{
		case FEMENUCMD_UP      : fedbm->OnUp(controller); break;
		case FEMENUCMD_DOWN    : fedbm->OnDown(controller); break;
		case FEMENUCMD_LEFT    : fedbm->OnLeft(controller); break;
		case FEMENUCMD_RIGHT   : fedbm->OnRight(controller); break;
		case FEMENUCMD_CROSS   : fedbm->OnCross(controller); break;
		case FEMENUCMD_TRIANGLE: fedbm->OnTriangle(controller); break;
		case FEMENUCMD_SQUARE  : fedbm->OnSquare(controller); break;
		case FEMENUCMD_CIRCLE  : fedbm->OnCircle(controller); break;
		}
	}
}
